+/**
+ * Download raw bytes from a Redmine path (for example an attachment).
+ * Retries like the JSON helpers. Throws on a non-2xx response, or when the
+ * response is larger than `maxBytes`.
+ */
+export async function redmineDownload(
+  host: string,
+  apiKey: string,
+  path: string,
+  username?: string,
+  maxBytes?: number,
+): Promise<{ bytes: Uint8Array; contentType: string | null }> {
+  const headers: Record<string, string> = { "X-Redmine-API-Key": apiKey };
+  if (username) {
+    headers["X-Redmine-Username"] = username;
+  }
+
+  let response: Response;
+  try {
+    response = await fetchWithRetry(`${host}${path}`, { headers });
+  } catch (e) {
+    throw new Error(
+      `Redmine GET ${path} request to ${host} failed: ${
+        e instanceof Error ? e.message : String(e)
+      }`,
+      { cause: e },
+    );
+  }
+
+  if (!response.ok) {
+    await response.body?.cancel();
+    throw new Error(`Redmine API GET ${path} failed (${response.status})`);
+  }
+
+  const declared = Number(response.headers.get("Content-Length") ?? NaN);
+  if (maxBytes !== undefined && declared > maxBytes) {
+    await response.body?.cancel();
+    throw new Error(
+      `Redmine GET ${path} is ${declared} bytes, more than maxBytes=${maxBytes}`,
+    );
+  }
+  const bytes = new Uint8Array(await response.arrayBuffer());
+  if (maxBytes !== undefined && bytes.length > maxBytes) {
+    throw new Error(
+      `Redmine GET ${path} is ${bytes.length} bytes, more than maxBytes=${maxBytes}`,
+    );
+  }
+  return { bytes, contentType: response.headers.get("Content-Type") };
+}
