  const headers: Record<string, string> = { "X-Redmine-API-Key": apiKey };
  if (username) {
    headers["X-Redmine-Username"] = username;
  }

  let controller = new AbortController();
  let timer: number | undefined;
  const resetIdle = () => {
    clearTimeout(timer);
    const c = controller;
    timer = setTimeout(
      () =>
        c.abort(
          new Error(`no data for ${idleTimeoutMs}ms`),
        ),
      idleTimeoutMs,
